TASK:{"title":"AERO9500 Preliminary Report (Part 1)","overview":"Design a new space mission benefiting Australia and identify main elements of its space segment. Demonstrate understanding of space segment systems (launch, orbits etc.) by developing a preliminary plan for the mission. Part 1 is a planning report to guide Part 2 main assignment."}
RUBRIC:[{"id":"C1","name":"Mission concept and rationale","weight":40,"max":40,"levels":[{"label":"Accomplished","min":7,"max":10,"desc":"Clear and complete description of mission goals, objectives, and requirements. Relates required mission function to users and needs. References literature as appropriate."},{"label":"Adequate","min":4,"max":6,"desc":"Sufficient description of goals, objectives, requirements. Users and needs identified. Lacks specific details and/or incomplete referencing."},{"label":"Deficient","min":0,"max":3,"desc":"Poor description with unclear goals, objectives, requirements. Insufficient identification of users and needs."}]},{"id":"C2","name":"Project plan","weight":30,"max":30,"levels":[{"label":"Accomplished","min":7,"max":10,"desc":"Robust plan with provision for variations and contingencies. Fits mission concept narrative, explains rationale. Includes appropriate information sources and references."},{"label":"Adequate","min":4,"max":6,"desc":"Plan presented but lacks some detail. Still sufficient to believe project is feasible."},{"label":"Deficient","min":0,"max":3,"desc":"Plan not included or lacks sufficient detail to demonstrate feasibility."}]},{"id":"C3","name":"Preliminary progress","weight":10,"max":10,"levels":[{"label":"Accomplished","min":7,"max":10,"desc":"Good preliminary results with brief description/interpretation. Clearly on track for completion."},{"label":"Adequate","min":4,"max":6,"desc":"Minor work completed. Results description or interpretation may be insufficient."},{"label":"Deficient","min":0,"max":3,"desc":"No actual or useful work completed."}]},{"id":"C4","name":"Report presentation","weight":20,"max":20,"levels":[{"label":"Accomplished","min":7,"max":10,"desc":"Clear logical structure, very easy to read, well-written with good spelling, grammar, appropriate style. Consistent formatting, appropriate clear graphical/tabular data, references match list and properly cited."},{"label":"Adequate","min":4,"max":6,"desc":"Not professional level but uses headings. Difficult to read, writing ok, some spelling/grammar flaws, language style not quite appropriate. Figures/tables labelled but formatting unclear/inconsistent causing loss of context. References mostly match and correctly cited."},{"label":"Deficient","min":0,"max":3,"desc":"Poorly structured, incoherent, lacks understanding of section purposes. Difficult to read, poor writing, many spelling/grammar errors, inappropriate style. Poor presentation impedes reading, inconsistent formatting, unlabelled figures/tables, references not cited or inconsistently cited."}]}]
MARKING:{"requirements":[{"id":"R1","met":"yes","page":2},{"id":"R2","met":"yes","page":2},{"id":"R3","met":"yes","page":3},{"id":"R4","met":"yes","page":5},{"id":"R5","met":"yes","page":4},{"id":"R6","met":"partial","page":4},{"id":"R7","met":"no","page":null}],"technical_issues":[{"page":4,"issue":"No hand calculations shown for orbit, launch, coverage or link budget despite requirement to supplement software with hand calculations."},{"page":4,"issue":"Preliminary progress claims only literature review and STK tutorials 1-4, no quantitative space segment design presented."}],"overall":"Mission rationale strong and well referenced. Project plan feasible with Gantt. Weak technical progress, lacking hand calculations and orbit specifics.","criteria":[{"id":"C1","level":"Accomplished","mark":8.0,"max":40.0,"reasoning":"Clear mission: reef bleaching monitoring for GBR, benefits Australia, identifies users and need. Good context and literature links with in-text citations.","evidence":[{"page":2,"quote":"Coral reefs, specifically the Great Barrier Reef, would immensely benefit from dedicated satellite monitoring"},{"page":2,"quote":"would allow marine and conservation scientists to more accurately predict and react"}]},{"id":"C2","level":"Adequate","mark":5.0,"max":30.0,"reasoning":"Gantt with tasks and deadlines present, tasks explained. Lacks contingency/variation planning and explicit rationale for sources; Useful Links listed separately.","evidence":[{"page":3,"quote":"Project work will be divided into weeks via a Gantt Chart"},{"page":4,"quote":"Background Research: This research will be ongoing throughout almost the entire design"}]},{"id":"C3","level":"Adequate","mark":4.0,"max":10.0,"reasoning":"Only literature reading and STK tutorials done. No technical calculations, orbit/launch analysis yet, so preliminary technical content minimal.","evidence":[{"page":4,"quote":"I have read the brief of Asner's monitoring system in Hawaii"},{"page":4,"quote":"also completed STK tutorials 1, 2, 3 & 4."}]},{"id":"C4","level":"Accomplished","mark":8.0,"max":20.0,"reasoning":"Well-structured with headings, good writing, consistent formatting. Gantt readable, references cited and listed matching.","evidence":[{"page":2,"quote":"Mission Concept & Rationale"},{"page":3,"quote":"Project Plan & Preliminary Progress"}]}]}
